xql_query:
// ============================================================
// Rule: TNB_EC2 Instance Exposing Secrets Detected
// Vendor: Tenable
// Objective:
// Detect activity associated with TNB_EC2 Instance Exposing Secrets Detected.
// Severity: SEV_050_CRITICAL
// Category: OTHER
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0006 - Credential Access
// Technique: T1552 - Unsecured Credentials

// Fonte de dados: logs brutos do Tenable
dataset = tenable_tenable_raw  

// Filtro para identificar apenas eventos com o título específico
// "EC2 Instance is exposing secrets"
| filter (title = """EC2 Instance is exposing secrets""")  

// Seleção dos campos mais relevantes para análise
| fields title,            // Título da detecção (descrição curta do achado)
         description,      // Detalhes adicionais do alerta
         accountName,      // Conta AWS associada ao recurso
         resourceOwner,    // Proprietário do recurso identificado
         sentBy,           // Origem do alerta/detecção
         policyName,       // Política que foi violada
         resources,        // Recursos afetados (ex.: ID da instância EC2)
         accountName,      // Conta AWS (repetido, mas útil para correlação)
         link              // Link direto para detalhes no Tenable
